"service_exec":false},{"signature":"telefone41.travar_conta(integer,integer)","sha256":"9f4ceb4902fe11ec0ce5387efb078ce40cd8c9781fd0421a0b8a2de05c2b26d7","config":["search_path=pg_catalog, pg_temp"],"secdef":true,"service_exec":false},{"signature":"telefone41.validar_conta(integer,integer)","sha256":"bbb0631c5ebb6635bb8d92535fd96c921cac07e455391a81987fabeb20022315","config":["search_path=pg_catalog, pg_temp","TimeZone=UTC"],"secdef":true,"service_exec":false},{"signature":"telefone41.validar_request(jsonb)","sha256":"0101ceb6069b181cae92f4f73c238a3fa1e65be63f7e43b9be0f63ebfc55f0b3","config":["search_path=pg_catalog, pg_temp"],"secdef":true,"service_exec":false},{"signature":"telefone41.validar_venda(integer,bigint)","sha256":"dd6c89109655009ad7172b24f81af12a2ec8f407d1e45f3854eb78603a3a8f01","config":["search_path=pg_catalog, pg_temp","TimeZone=UTC"],"secdef":true,"service_exec":false},{"signature":"telefone41.verificar()","sha256":"61f4f5e1b59449ff701d301e38c014ae7e1bb073eee6dab0a508cd3651ae8f85","config":["search_path=pg_catalog, pg_temp"],"secdef":true,"service_exec":false}]'::jsonb) LOOP
  SELECT p.* INTO f FROM pg_proc p WHERE oid=to_regprocedure(e->>'signature');
  IF NOT FOUND OR encode(extensions.digest(f.prosrc,'sha256'),'hex') IS DISTINCT FROM e->>'sha256'
   OR to_jsonb(f.proconfig) IS DISTINCT FROM e->'config' OR f.prosecdef IS DISTINCT FROM (e->>'secdef')::boolean
   OR pg_get_userbyid(f.proowner)<>'postgres'
   OR has_function_privilege('service_role',f.oid,'EXECUTE') IS DISTINCT FROM (e->>'service_exec')::boolean
   OR has_function_privilege('anon',f.oid,'EXECUTE') OR has_function_privilege('authenticated',f.oid,'EXECUTE') THEN
   RAISE EXCEPTION '49 flight pin mismatch %',e->>'signature' USING ERRCODE='55000'; END IF;
 END LOOP;
